    shop_hol_not_now: "暂时不用",
    faq_a_shop_delivery: "在购物清单里点卡车：选择配送里有什么（默认全选）、什么时候送到——今天、明天或其他日期——以及几点送到（上午、下午、晚上，或选「其他…」自定时间）。这些物品会移到清单顶部的「配送中」卡片里，并显示日期和时间段。到了那天，「我的一天」里会出现「配送送到了吗？」（卡片上也有「送到了吗？」）。如果全部送到，它们会移到「再次购买」。如果少了东西，点一下没送到的，它就会直接回到清单。",
    faq_a_shop_departments: "清单会自动按超市分区排列——果蔬、面包、乳品蛋类、肉禽水产、粮油调味、冷冻食品、饮料、零食、清洁、个护、婴童和宠物——这样你就能按顺序逛完货架。分区是根据物品名称识别的。如果某个物品放错了地方，点一下它并选择分区，或选「其他…」自己填写。",
    faq_a_shop_share_qty: "可以。每个物品旁边，+ 加一个（×2、×3…），− 减一个。购物清单顶部的分享按钮会把整张清单按分区整理好，通过 WhatsApp、邮件或复制发送。",
    faq_a_shop_two_buttons: "两个都表示「已买」。✕ 用于只买一次的东西：它会离开清单（并在 🗑️ 存档里等着，以防点错）。↺ 用于经常要买的东西：它会离开清单，在「再次购买」里等着；清单底部垃圾桶旁边的小 ↺ 按钮可以打开它，在那里点一下就能把物品放回清单。在里面的「编辑」中可以把物品移除。添加物品时，以前买过的东西会作为建议出现；如果它已经在清单里，只会变成 ×2，而不会多出一行。",
    faq_q_shop_delivery: "「我下了配送订单」怎么用？",
