    faq_a_weekly_table: "在日历视图中，月度概览旁边有一个每周表格——它默认是折叠的，点一下标题即可展开。它按时间显示一周中每一天的事件和任务，以及每周重复任务；‹ › 可以切换周，点一下某一项即可打开编辑。",
