    nm_demo_title: "怎样更换一餐",
    faq_a_new_me_challenge_journal: "挑战结束时——无论是大挑战、小挑战还是本周挑战——庆祝画面里都有一个 📝 感觉怎么样？ 按钮。它会打开挑战日记里的一页：感觉如何（五张表情）、什么有帮助、哪里比较难、我能从中带走什么——都不是必填，也可以留到以后再写。日记是魔法背包里的一颗钻石：每个完成的挑战都附有日期和写下的内容，最新的在最前面——点一个就可以阅读、编辑或分享（只会分享这一页上的内容）。完成的挑战还会在成就里得到一枚奖牌，位于“我完成的挑战”之下。挑战日记和普通日记是分开的。",
    faq_q_new_me_challenge_journal: "挑战日记是什么？",
