    nm_chj_title: "挑战日记",
    nm_chj_write: "写下这次怎么样",
    nm_swap_time: "时间",
    faq_a_ai_reminder_in_text: "可以——和任务写在一起就行，例如「明天17:00取快递，提前一小时提醒」。提醒会直接保存在任务上：提前一小时、半小时、提前一天等等都可以；只写「提醒我」而不写时间，表示提前10分钟。文字里写的提醒优先于同一窗口中的提醒栏。",
    faq_q_ai_reminder_in_text: "可以在同一个请求里让AI助手顺便设置提醒吗？",
    myday_meals_all_done: "今天的餐食都已打卡 🍽️",
    nm_tour_week_text: "一周的小挑战。每天点 ✓——最后得到一把钥匙。",
    books_home_chip: "{title} · 第{page}页",
    books_home_of: "共 {total} 页",
    books_home_off_toast: "这本书已从主屏幕移除",
    books_home_on_toast: "这本书已显示在主屏幕 📖",
    books_home_pin: "显示在主屏幕",
    books_home_q: "我读到第几页了？",
    books_home_save: "保存",
    faq_a_books_home_chip: "可以。在阅读角里，点一下正在读的书的卡片上的 📌 显示在主屏幕。主屏幕的问候语下方会出现一个带有书名和页数的小按钮——点一下，输入新的页码并保存，进度就会被记录（阅读角里也一样）。再点一次 📌 即可取下。可以同时显示好几本书——每本一个按钮——所有设备上都相同。",
    faq_a_new_me_week_challenge: "一个为期一周的小挑战，由自己选择。走廊里有一张大卡片：“这周想在哪方面努力？”——点一下，选一个领域（与自己、与他人、学习与成长、平静、勇敢的小步伐、家与日常）和一个挑战，再决定何时开始。同样的挑战也在挑战页面里，位于 🌱 个人成长之下。每天在卡片上打 ✓（每周可休息一天），每结束一周，就能为秘密世界得到一把新钥匙。“每天读 2 页”会根据在阅读角记录的页数自动打勾。一周结束后，选择 📌 保留为每日任务，就会按选定的时间把它加入我的日常，每天都有 ✓。同一时间只能进行一个本周挑战；大挑战和小挑战会继续与它并行。",
    faq_a_room_genie: "在海边门廊上，点一下阿拉丁神灯，森林精灵就会现身，随后开始一段对话：你的愿望是什么（想改变生活中的什么），愿望实现时会是什么感觉，路上有什么困难，以及怎样把眼前的处境变成好事。接着是大概需要多久、一个小小的第一步和另外两步，还有一句遇到困难时用的“如果……那么……”。最后，整个愿望会一步一步地呈现出来，可以把它变成我的目标里的一个目标（这些步骤会成为路上的里程碑，日期按所选的时长安排；在那里一切都可以修改），也可以保存到日记里——之后精灵就会道别。不选择其中任何一个，就不会保存任何内容。从第二次来访开始，精灵会先问你还想不想改变生活中的其他事情：选“想”——同样的对话；选“暂时不用”——提醒你去实现已经定下的目标。精灵每天出来一次：保存一个愿望之后（或选“暂时不用”之后），它会休息到明天。这些问题遵循一种广为人知的把愿望变成计划的方法：愿望、结果、障碍和计划。",
    faq_q_books_home_chip: "能在主屏幕上看到我的书和页数吗？",
    faq_q_new_me_week_challenge: "什么是本周挑战？",
