    nm_me_on_screen: "显示中",
    faq_a_new_me_game: "在 New Me 里，游戏按钮始终在同一个位置——在走廊、秘密房间和森林里的任何地方都一样；只有中间的画会变。顶部：旅程中的第几天、钥匙、连续天数和今天的能量（计划中已经吃了多少），下面是下一个任务——到点的下一餐（点一下即可打开，里面有 ✓ 我吃了）。侧边：全天、挑战和我的旅程，旁边是本周挑战——它的 7 天和今天的 ✓。底部：魔法背包（整个 New Me——世界地图、我的旅程、购物清单、成就、挑战日记、身体围度、进度照片、月历、每日表格、提醒、菜单 PDF 和设置；它会作为独立的屏幕打开）。世界地图是背包里的第一样东西，显示森林里的所有地方——点一个地方就能过去；上锁的地方会显示需要几把钥匙。Sky 是你在森林小路上的角色：从 Sky 1 开始，完成几个挑战后（4 把钥匙）成长为 Sky 2，接近尾声时（9 把钥匙）成长为 Sky 3——变身过程看得见。点 Sky 可以查看所有阶段——已经达到过的阶段都可以再次选择，所以之前的阶段可以回来。Sky 会漂浮——用手指或鼠标拖动他，他碰到的入口就会打开（上锁的入口会显示还差几把钥匙）。Sky 也会跟着你进入每个房间和地点，你把他留在哪里，他就漂浮在哪里：可以把他拖到任何地方，拖动他脚下发光的圆环就能让他整圈转动；他会面朝移动的方向（在电脑上：方向键移动他，Q 和 E 转动他）。在走廊中，顶部栏下方的小 🏠 可返回主屏幕；在每个房间和地点，同一个角落的按钮可返回走廊。",
    faq_q_new_me_game: "游戏按钮、世界地图和 Sky 是怎么运作的？",
