    faq_a_new_me_menu_build: "首先，问卷会问你吃哪几餐、什么时候吃（2 餐 + 1 次加餐、2 餐 + 清淡晚餐，或两者都有），以及晚上有没有要吃或喝的、吃喝什么、几点。选“2 餐 + 1 次加餐”时，两餐是午餐（11:30）和晚餐（19:00），加餐在 16:00。然后会显示这些餐的所有选项。每餐最多选 2 个最爱——菜单上会显示“这个 或 那个”。有些选项（皮塔饼配酱、玉米片配牛奶、清淡小食）可以最多选 3 样喜欢的，每样都有自己的份量，菜单上会显示“这个 或 那个 或 另一个”；热量按所选的来算。咖啡和饮品也一样。每个选择都会被平衡，所以一天的总量正好是 1300 或 1500。随时想改：⚙️ 设置 → 🍽️ 制定你的菜单，或者在餐卡上点“最多选3种喜欢的”。",
