    faq_a_myday_water_toggle: "可以。「我的一天」里的水杯（点 + 再加一杯）默认显示。要隐藏它，在 设置 > 个性化与日历 中关闭「在『我的一天』显示喝水」。不会删除任何内容——饮水记录照常使用，重新打开后水杯就会回来。",
    faq_q_myday_water_toggle: "可以隐藏「我的一天」里的喝水吗？",
    myday_water_toggle_label: "在「我的一天」显示喝水",
    faq_a_routine_newme_sync: "有 New Me 时，「我的日常」的 ⚙️ 里有一个「与 New Me 同步」开关。开启时（默认），今天的 New Me 餐食会显示在「我的一天」和「我的日常」里——代替被隐藏的日常餐食。关闭后，New Me 的餐食会从两处移出，日常完全恢复原样。不会删除任何内容——再次开启会恢复一切，并询问要隐藏日常中的哪些餐食。",
