    faq_a_food_list_languages: "内置的食物列表最初收录的是以色列食物及其希伯来语名称。在其他所有语言中，每种食物都以英文名称显示，搜索会匹配它知道的任何英文名称（例如 'broth' 会找到 Clear soup）；只有希伯来语名称的食物不会出现。列表里没有的，直接用自己的话写下来即可——AI 估算适用于所有语言。",
    faq_q_food_list_languages: "为什么在我的语言中，食物列表显示英文名称，而且食物更少？",
    settings_copyright_line: "© 2026 版权所有。应用开发：eden zabari",
    workout_ready_replace_btn: "替换",
    faq_a_sport_workout_ai: "在\"我的锻炼\"→ ⋯ →\"AI 计划\"（表格为空时，也可以点现成计划旁边的方块）。点几下回答：每周几次、什么时候、地点、水平和目标，大多数都有\"其他\"——如果愿意，还可以写一行补充，比如膝盖比较敏感，或想在夏天前跑完 5 公里。AI 会生成完整的一周：锻炼类型、日期、时间、时长、强度、动作和休息日。保存之前会先预览：\"放进我的表格\"（替换表格或加在后面）、\"换一个建议\"（最多 3 次）或\"修改答案\"。计划刻意保持温和；如果提到疼痛或受伤，会给出更温和的选择，并建议先咨询专业人士。它和日程、日常的 AI 共用同一额度：免费 5 次，高级版每月 60 次。",
    faq_q_sport_workout_ai: "怎么用 AI 制定锻炼计划？",
