    workout_ai_when_noon: "中午",
    workout_ai_when_ph: "例如下班后，或 17:30",
    workout_ai_working: "正在生成计划…",
    faq_a_sport_workout_jar: "每种锻炼都有自己颜色的星星——跑步是粉色，步行是绿色，游泳是蓝色，等等。本周记录的每一次锻炼，无论来自表格还是单独记录，都会把它的星星落进\"我的锻炼\"顶部的罐子里，罐子会一点点装满，直到达成每周目标（点一下就能修改目标）。达成目标时罐子会发光。旁边的小罐子记录你连续装满了几周。",
    faq_q_sport_workout_jar: "\"我的锻炼\"里的彩色星星和罐子是什么？",
    faq_a_sport_workout_gcal: "可以——在 ⋯ → Google 日历（先在设置里连接 Google 日历）。每个设了时间的锻炼都会变成在对应日子每周重复的日程，应用里的修改也会同步过去。提醒只来自应用，所以 Google 不会另加提醒，锻炼也不会在应用里出现两次。再点一次，只会从 Google 日历移除锻炼。",
    faq_q_sport_workout_gcal: "我的锻炼能显示在 Google 日历里吗？",
    workout_gcal_btn: "Google 日历",
    workout_gcal_error: "无法更新 Google 日历——下次修改时会再试",
    workout_gcal_not_connected: "请先在设置中连接 Google 日历",
    workout_gcal_off_toast: "锻炼已从 Google 日历移除",
    workout_gcal_on_toast: "你的锻炼已加入 Google 日历",
    faq_a_sport_workout_reminder: "可以——在锻炼里的\"提醒\"选择提前 10 分钟、30 分钟或 1 小时，或自定义时间（锻炼需要设定时间）。它和其他提醒一样响铃，只提醒一次、只在一个地方：应用开着就在应用里，否则在手机上。\"完成\"会把锻炼记入历史，\"还没\"会在 5 分钟后再提醒。",
    faq_q_sport_workout_reminder: "锻炼前能收到提醒吗？",
    workout_reminder_30min: "提前30分钟",
    workout_reminder_label: "提醒",
    workout_reminder_need_time: "设定时间后才能收到提醒",
    faq_a_sport_workout_share: "在 ⋯ → 分享里，一周会变成一张主题色的玻璃风图片，并附上一个不显眼的应用链接（手机上直接打开分享菜单，电脑上会保存图片）。⋯ → 打印用 PDF 会打开一整周的清爽页面，每个锻炼和动作旁都有可以打勾的方框——选择\"另存为 PDF\"或直接打印。计划也会出现在设置里数据报告的运动部分。",
    faq_q_sport_workout_share: "怎样分享或打印我的一周锻炼？",
    share_image_saved: "图片已保存——可以附上发送",
    share_save_image: "保存图片",
    workout_pdf_btn: "打印用 PDF",
    workout_share_btn: "分享",
    faq_a_sport_workout_board: "在 ⋯ → 周看板里，每天是一列：把锻炼拖到另一天（手机上先长按）。在锻炼里打开\"也放进我的日常\"，它会按时间和日期进入你的日常，改动双向同步；在我的日常的某一项里，\"添加到我的锻炼\"则反过来。任意一边打 ✓ 两边都算，在\"我的一天\"里只出现一次——在饮水旁的小标签里。",
    faq_q_sport_workout_board: "怎样把锻炼挪到另一天，并和我的日常连起来？",
    routine_in_workouts_btn: "在我的锻炼中打开",
