    workout_delete_confirm_routine: "它会从计划和我的日常中移除。已记录在历史里的锻炼会保留。",
    workout_moved: "已移到{day}",
    workout_routine_need_time: "要放进我的日常，需要先设定时间",
    workout_routine_toggle: "也放进我的日常",
    workout_view_board: "周看板",
    workout_view_timeline: "时间线",
    faq_a_sport_workout_plan: "在\"锻炼记录\"的\"我的锻炼\"里：+ 锻炼——类型、日期、时间、时长、强度和地点（也可选\"其他\"）。力量、功能训练和游泳可以带一份动作清单，\"休息\"用来标记休息日。也可以从现成计划开始。今天的锻炼会大大地显示，下面是整周；✓ 会连同强度一起记入锻炼历史。在 ⋯ 里设定每周目标（次数或分钟）——每完成一次锻炼，它的星星就会落进罐子里。",
    faq_a_sport_workout_today: "在\"我的一天\"里，饮水旁边有一个小标签显示今天的锻炼——点一下会打开详情、✓ 和 ▶。▶ 开始计时，计时也会在主屏幕的小标签里继续，\"结束\"会按实际时间记录锻炼。如果 New Me 的挑战\"两周动起来\"正在进行，记录的锻炼会自动计入。",
