    faq_a_new_me_magic_themes: "New Me 自带的五款闪亮主题：魔法森林、星尘、玫瑰仙子、魔法极光和金色黄昏。在 New Me 里（⚙️ 设置 > 颜色）或在 设置 > 外观与显示 里选择一款，一支闪光的画笔就会把屏幕刷成这个主题。魔法主题会让整个应用和每次点按都闪闪发光。随时可以换回任何其他主题。",
