    apptour_m_presets_text: "你的常用餐都在一处：搜索、最近使用、按时段分类——点 ＋ 就能加到今天。",
    apptour_night_text: "🌙 让整个应用变暗，☀️ 把白天带回来。",
    apptour_noteline_text: "写下来点 ➤，就会存进笔记。行首的 📝 可以切换成 🛒 购物或 🍎 常用餐。",
    apptour_search_text: "笔记、购物、日历、食谱、笔记本、目标、表格和书——一次搜索全都能找到。",
    faq_a_new_me_ai_menu: "在菜单之前，问卷会问你吃哪几餐、什么时候吃（2 餐 + 1 次加餐、2 餐 + 清淡晚餐，或两者都有），晚上是否吃点小东西、几点，有什么不吃，以及怎么喝咖啡或茶。然后 AI 为每一餐制定 3 个选项——每个都按这一餐在一天中的份额来定量，所以一天的总量仍然正好是 1300 或 1500——还会给出饮品建议，并保存为你的常用饮品。每餐最多选 2 个最爱；原始菜单的选项就在下面，在 🔄 替换 里它们排在专属菜单之后。🔄 换一批 会生成新的一组（每份问卷最多 3 次）。随时想改答案或重新制定菜单：⚙️ 设置 → ✨ 专属菜单（AI）。",
