    room_back_to_shelf: "回书架",
    faq_a_new_me_day_total: "每天都正好等于计划：餐食、白天约 150 千卡的咖啡和饮品，以及晚上选的内容——吃点小东西或喝点饮品。晚上最多选3种喜欢的（比如一根香蕉、一份酸奶或2小块黑巧克力；或者花草茶、加少许牛奶的茶或温牛奶），它们的热量从餐食里扣。每个选择都会自动平衡：更小或更大的选项、去掉的一餐、小早餐和搭配它的小餐，或者晚上——差额按每餐的大小加到餐食里或从中扣除，每餐下面都写着多少（+ 或 −）以及可以加什么或减什么。已经打勾的一餐保持记录时的样子。在问卷里，每餐旁边显示它的调整，一个小框显示餐食、饮品、晚上和合计。那天想吃点别的？保持总热量不变或更少就好。",
