    books_quotes_chip: "摘句",
    faq_a_book_quotes: "在秘密房间的书架上（摘句），或阅读角里的小标签\"💬 摘句\"——是同一个列表。点\"+ 摘句\"，写下句子，再从阅读角选书，或用\"✏️ 其他\"输入别的书名；作者可不填。✏️ 编辑摘句，🗑️ 删除。 摘句是一张张可以滑动的书签——顶部的 🎨 可以换成照片或卡片墙。",
    faq_a_room_wish_jar: "秘密房间的书架上有一个装梦想的玻璃瓶。点最上层的小瓶子（或 书架 > 愿望瓶），写下你希望生活是什么样子——尽情去想，没有对错。每个愿望都会折成一张纸条，落进瓶子里。“抽一张纸条”会随机打开一张，每张纸条也都能单独打开。同一个愿望打开第二次起，就可以把它变成目标，并分成小步骤。每周一次，会轻轻出现一张写着你某个愿望的纸条——没有压力，只是提醒你要去的方向。",
