    faq_a_notes_sticky_look: "便签是一列简短的玻璃卡片——便签顶部的 🎨 可以切换所有便签的外观（列表、上方的日期按钮和写便签的窗口）：玻璃、简洁列表、索引卡或和纸胶带。正在拖动的便签会完全保留自己的外观和颜色。点按便签的文字即可打开——在里面可以编辑、更换颜色，还能看到最后一次写的时间。完成后点 ○，点 × 会把它移到存档（列表底部的 🗑️ 可以找回）。按住 ⠿ 拖动可以调整顺序、拖到“以后再说”下面，或拖到上方的某一天。 ! 可以把便签标为紧急——它会轻轻移到最前面几行，并带上一个小小的“紧急”标签；再点一次即可取消。",
