    faq_a_routine_clash: "如果同样的日子里那个时间已经有事项，会出现两个选择：“替换”——新事项占用这个时间，再为原来的事项选一个时间（编辑已有事项时，会建议用它原来的时间，两者就直接互换），或者“都要”——两个都留在同一时间，一上一下。如果日子不同（比如一个是周日到周四，另一个是周五），就完全不会问。",
