    faq_a_new_me_coffee: "今天的菜单下面有一个简短的小结：今天所有餐食加起来多少千卡、咖啡和饮品还剩多少，还有已选咖啡和饮品的按钮——点一下就会加到饮品里。在按钮下方的“最多选3种喜欢的”（问卷里也有）里选择显示哪些：水 / 苏打水、花草茶、无糖汽水、黑咖啡 / 美式（~5）、加少许牛奶的茶（~25）、用水冲加不超过100毫升牛奶或植物奶的咖啡（~50）、低卡热可可、温牛奶或普通咖啡 / 拿铁（~120）。",
