    faq_a_recipe_examples: "在你自己的食谱下面有示例食谱：早餐、沙拉、汤、主菜、配菜、小吃、甜点和纯素菜，每个都标有准备时间、每份卡路里以及一份有多少克。点一下食谱即可打开，“保存到我的食谱”会生成一份你自己的副本，可以编辑。分类标签可以筛选，再点一次同一个标签就会显示全部。",
