    faq_a_new_me_small_breakfast: "一份轻早餐（约170千卡）：1个斯佩尔特小麦皮塔饼（不超过100千卡）配抹酱或奶酪，外加一份蔬菜——最多选3种喜欢的，比如1茶匙巧克力酱、1茶匙花生酱或1片硬质奶酪（脂肪不超过22%）。因为它分量小，会在另一个时间搭配“再加一份小餐”（一个半小时后，比如 11:30 → 13:00——也可以选别的时间）：再来一个皮塔饼配酱、高蛋白酸奶配水果、米饼配奶酪、麦片配牛奶或半个皮塔饼配鸡蛋——最多约200千卡，有自己的 ✓。剩下的热量会分给其他几餐，每餐都会显示增加了多少，所以全天总量仍然符合计划。可以在问卷里选择它，也可以用 🔄 只在今天换成它——比如早餐吃得晚的时候。",
