    faq_a_new_me_favorites: "可以。在问卷里（以及从设置重新填写时），每餐最多可以选 2 个选项。第一个显示在菜单里，下面有一行“或”显示第二个——点一下就只在今天换成它。如果早餐没按时吃，“⏰ 晚点”会把它挪到今天晚些时候，热量不变。",
    faq_a_theme_mode: "有些特别主题在深色下最好看——水彩、北极光、芭比和两个闪亮主题——所以选择其中一个会把应用切换到深色模式，选择其他任何主题（包括火箭）则切换到浅色模式。黑色和深灰色保持深色。之后随时可以用菜单里的 🌙 或设置里的\"浅色模式\"切换。",
