    faq_a_room_records: "唱片机从一开始就在房间里，放在扶手椅旁的树桩上。它的唱片会在 YouTube 上打开近几年大热歌曲的官方 MV，下面还有五首安静的旋律，就在房间里播放——播放时唱片会转动，点「⏹ 停止」即可关掉音乐。",
