    faq_a_ai_chat_food_fix: "可以。在聊天中回答的下方点 ✏️ 修改卡路里 / 蛋白质，改好数字后点保存。只会改动刚刚添加的部分——即使它被并入了已有的加餐。AI 可能会出错，所以值得快速核对一下。",
    faq_a_new_me_home_btn: "如果你有 New Me，主屏幕顶部专注模式旁边的小 💎 会打开今天的菜单。今天的餐食也会出现在「我的一天」里，每一餐都有 ✓。",
    faq_a_routine_item_days: "可以。在「我的日常」里点一下该项，在 📅 星期 中选择它的日子——比如只在周一到周五。其他日子它不会出现在「我的一天」里，也没有 ✓；在「我的日常」里它仍然保留，颜色变淡，旁边显示它的日子。连续 3 天没有 ✓ 时询问该项的卡片，也只计算这一项自己的日子。",
