    faq_a_home_note_line: "在主屏幕中间的那一行里写，然后点 ➤（或按回车）——就会保存到笔记里。点一下行首的 📝，它会变成 🛒：这时写的内容会进入购物清单。再点一次变成 🍎：输入几个字，匹配的保存餐食就会出现，点一下就会记入今天的饮食。用 🎤 可以直接说出来。",
    faq_a_night_mode: "打开菜单 ☰，点顶部的 🌙——整个应用会变暗。同一位置的 ☀️ 可以切回白天。在设置的“浅色模式”里也可以切换。",
    faq_q_home_note_line: "怎么在主屏幕上写快速笔记？",
