    menu_day_mode: "日间模式",
    menu_night_mode: "夜间模式",
    faq_a_secret_room_yoga: "森林小路的尽头有一座发光的大门，门后的瀑布旁，森林里的小生灵们——露米、泡芙、妮克丝和斯帕克莉特——围成半圆，坐在各自的垫子上，瑜伽老师芙洛拉面对它们，坐在石头上那张单独的垫子上。点一下芙洛拉：她睁开眼睛，一切都靠近过来，对话慢慢开始，留有阅读的时间——芙洛拉问大家过得怎么样，每个小生灵用自己的名字回答（每一行旁边都有说话者的小画像），然后她会问你和身边亲近的人在一起感觉如何。对话会根据你的回答继续——好人、难相处的人，或有点孤单。每条路都以一个小任务（可以直接加入「我的一天」；如果任务是写点什么，会有地方可以写，写下的内容会保存到魔法日记里）和一起呼吸三次的瑜伽姿势结束。↩ 退回一步，✦ 开始新的对话。下一把钥匙会打开瀑布：坐在石头上，一切都会隐去，只剩下水声。俯身看向水池，水面会浮现一个问题——真正的你今天会做什么？——你的回答会变成「我的一天」里的一个小任务。这是一个温柔的时刻，但不能代替和专业人士交谈。",
    faq_q_secret_room_yoga: "森林瑜伽里会发生什么？",
