    faq_a_new_me_times: "在一开始的问卷里，或随时在 New Me 设置 →“用餐时间”里设定。如果日常里已经有用餐时间，会直接从那里导入——还可以隐藏日常里的餐，改为显示 New Me 的餐。如果没有，就选择一天吃几餐（2 餐 + 1 次加餐 / 2 餐 + 清淡晚餐 / 2 餐 + 1 次加餐 + 清淡晚餐）以及每餐的时间。选“2 餐 + 1 次加餐”时，就是 11:30 午餐、16:00 加餐、19:00 晚餐（每个都可以改）。这就是你在各处的用餐时间：走廊、“我的一天”、“我的日常”和提醒里都一样。无论怎么选，一天的热量都不变：去掉的部分会分给其他几餐。",
