    faq_a_routine_exact_time: "可以。用精确时间向 AI 描述日常时（例如\"16:10 交易\"），会原样保存，不会四舍五入到整点。日常里写下的内容一定会显示在面板上，即使那个小时没有在时间设置里选中；删除有内容的时间时，会先询问。也可以手动修改时间：在条目的窗口里点一下时间，选择小时和分钟。",
