    faq_a_routine_ai: "在“我的日常”里打开 ⚙️（或 ➕），点“用 AI 建立新日常”：用简单的话描述你的日常——例如“7 点起床，8 点健身，工作到 17 点”——AI 会建立一个带时间和事项的新标签页。如果文字里写了哪几天（“工作日”），标签页就在那几天打开；不同日子的不同日常会变成各自的标签页。之后一切都可以照常编辑。",
    faq_a_routine_daysoff: "在“我的日常”里点 ➕，再点“休息日”：选好日子（例如周六和周日），再选这几天的日常——不排日程（保持空白）、你自己的日常，或者告诉 AI 你会做什么，让它来建立。休息日有自己的标签页，在这些日子里，“我的日常”和“我的一天”只显示这个标签页。",
