    faq_a_secret_room_diary: "只有你自己。日记页面保存在你的账户里，所以每台设备上都有，别人都看不到。秘密房间书桌上的魔法日记可以打开它，音乐角的日记也可以。新页面下方有一个折叠的月历：有页面的日子会有一个圆点，点一下那天就会打开当天的页面，也可以在那里删除页面。日记打开后，也可以把它加入主菜单——用日记里或 New Me 设置里的开关。",
    faq_a_secret_room_places: "森林大门的每个入口都有自己的钥匙。入口后面是：面朝大海的门廊（小桌上有阿拉丁神灯——点一下，森林精灵就会在魔法薄雾中从灯里升起，盘旋一圈，开始一段关于你愿望的对话——见“神灯精灵有什么用？”）、吉他和日记（吉他会奏出一段简短而安静的旋律，并自己停下；挂在树上的三张唱片各自奏出一段神奇的旋律——再点一下即可停止——树桩上的日记用来书写）、呼吸室（日落时宁静的湖，水面上漂着一盏莲花灯：点一下，写下愿望，它会带着愿望漂远，回到湖的深处；也可以用魔法棒在沙地上写下想放下的事，它会一直留着，直到你用手指抹掉），以及森林小路（夜晚才会开启，点灯笼就会切换成白天；大树枝上挂着一架神奇的秋千，长椅可以坐，点一下指示牌会拉近看：一块写着六个小问题、可以打勾的木板）。上锁的入口会显示还差几把钥匙。小路尽头，一座发光的大门通向瀑布旁的瑜伽，再从那里通往瀑布本身。",
