    dev_weather_preview_label: "预览——仅在你的账户中：",
    faq_a_ai_chat: "点一下气泡就会打开对话。选择要做的事——加到日历的事、吃了什么、食谱照片或新表格——或者直接写，助手会自己判断。也可以点 🎙️ 直接说话，不用打字。日历可以选择一次、每周或每天。回答会出现在对话里，接着可以继续做别的事，或打开日历 / 吃了什么。",
    faq_a_new_me_hall: "New Me 从一座魔法森林的大门开始，森林里的每个入口都是一个地方：巨树上的圆门通往秘密房间，空心树干通往面朝大海的门廊，蘑菇屋通往吉他和日记，小柳树拱门通往呼吸室，大柳树拱门通往森林小路，带梯子的花拱门在星空屋顶打开后可以爬上去。上锁的入口会显示一把锁。小路上漂浮着你的角色 Sky，周围是游戏按钮：下一个任务、本周挑战、装着整个 New Me 的魔法背包、世界地图和各种工具。点顶部的钥匙，会说明怎样获得钥匙。",
    faq_a_new_me_routine_meals: "当 New Me 里设定了餐食、而“我的日常”里也有餐食时，New Me 会询问是否隐藏它们，改为显示 New Me 的餐食——以免重复显示。之后“我的日常”会在对应时间显示 New Me 的餐食，带有 💎 和 ✓；点餐食的名称会打开一个窗口，可直接在日常上方选择另一餐或更改它的时间。不会删除任何内容：可以在 New Me 的 ⚙️ 设置 → 日常中的餐食 里恢复，或者在“我的日常”的 ⚙️ 里关闭“与 New Me 同步”。没有启用 New Me 时，它们会自动恢复。",
    faq_a_room_computer: "这是一段小对话，从“今天到现在过得怎么样？”开始——不错、忙碌还是辛苦——然后一步一步陪你往下走，最后得到一个小任务（也可以直接加入“我的一天”）。回答可以点选，也可以自由输入——输入的内容会对应到最接近的回答。“↩ 返回”可以退回一步换个回答，“新对话”随时从头开始。忙碌或辛苦的一天之后，可以在同一天稍晚回到电脑前：“我回来了...”会接着之前的对话。下方的绿灯可以关闭和打开电脑。只保存你的选择，只在这台设备上，并且只保存到当天结束。",
    faq_q_ai_chat: "怎样和助手对话？",
