    pcx_c1a_t: "如果可以——闭眼 15 分钟。如果不行——用冷水洗把脸，喝一大杯水，缓口气。",
    pcx_c1a_tn: "小睡一下或冲冲冷水",
    pcx_c1b_q: "情绪压力往往直接积压在身体和肌肉里。稍微放松一下，能帮忙降降火。",
    pcx_c1b_r1: "压力真的体现在我身上了",
    pcx_c1b_s: "身体一旦卸下负担，大脑就会收到“一切都好”的信号。",
    pcx_c1b_t: "把肩膀放下来，用腹部深呼吸 3 次，慢慢转动脖子。",
    pcx_c1b_tn: "放松伸展",
    pcx_c2_o1: "觉得不被理解 / 被不公平地对待",
    pcx_c2_o2: "还在翻腾的怒气",
    pcx_c2_q: "和人的摩擦或艰难的对话，会留下沉重的余味，可能毁掉一整天的平静。这件事里最让你困扰的是什么？",
    pcx_c2a_q: "觉得不被看见、不被理解，真的很让人沮丧。想在这里用文字把它说出来吗？",
    pcx_c2a_r1: "好，事情是这样的...",
    pcx_c2a_r2: "不了，我不想深挖",
    pcx_c2a_s: "完全合理。有时候，先把它放到一边，是最健康的一步。",
    pcx_c2a_t: "提醒自己：别人的解读并不是绝对的真相——让这份委屈先休息到明天。",
    pcx_c2a_tn: "情绪的界线",
    pcx_c2b_q: "愤怒是一股需要释放的强大能量，否则它会从内部侵蚀我们。",
    pcx_c2b_r1: "我只想把怒气发泄出来",
    pcx_c2b_s: "那我们就安全地把它释放出来，不伤害自己。",
    pcx_c2b_t: "打几下枕头，快走 5 分钟，或者把所有怒气写在一张纸上——然后撕掉。",
    pcx_c2b_tn: "身体释放",
    pcx_c3_o1: "日程一团乱 / 花了很久的东西出了故障",
    pcx_c3_o2: "觉得失败 / 努力做的事没成功",
    pcx_c3_q: "在一切都不顺的日子里，会有一种无力感。今天最主要出问题的是什么？",
    pcx_c3a_q: "当事情超出我们的控制时，唯一的规则就是切换到“轻松生存模式”。今天有什么可以取消的？",
    pcx_c3a_r1: "我取消了一些，但还是有压力",
    pcx_c3a_s: "降低期待不是放弃——而是日常的智慧。",
    pcx_c3a_t: "选一件今天的任务，正式放下它，给自己留一点喘息的空间。",
    pcx_c3a_tn: "降一挡",
    pcx_c3b_q: "失望会痛，尤其是在付出努力之后。但一次没成功的尝试只是一条信息——并不能定义我们是谁。",
    pcx_c3b_r1: "它还是让我很低落",
    pcx_c3b_s: "低落是可以的。给它一点空间，不要批评自己。",
    pcx_c3b_t: "现在就做一件让自己舒服的小事（一杯热饮、一首喜欢的歌）。",
    pcx_c3b_tn: "善待自己",
    pcx_c4_o1: "安安静静地，不跟太多人说话",
    pcx_c4_o2: "想找点小东西来安慰自己或打打气",
    pcx_c4_q: "这也完全有它的位置。想给自己一点温柔和安静，并不总是需要解释原因。你想怎样度过今天剩下的时间？",
    pcx_c4a_s: "安静是很好的充电器。今天你可以稍微保持一点距离。",
    pcx_c4a_t: "在接下来的一小时里，把手机调成静音或“勿扰模式”。",
    pcx_c4a_tn: "泡泡时间",
    pcx_c4b_s: "在灰蒙蒙的日子里，小事能带来大不同。",
    pcx_c4b_t: "为今晚选一件开心的事（一部好电影、一个热水澡、一顿美味的饭）。",
    pcx_c4b_tn: "一点小犒赏",
    pcx_c_end1: "值得记住：难熬的一天不等于难熬的人生——它只是整本书里的一页。明天是新的一天。",
    pcx_c_end2: "祝你有个平静温柔的夜晚。如果还需要倾诉，或者晚点又觉得难受——我在这里。回来就好，我们聊聊。",
    pcx_c_o1: "身体不舒服 / 累得要命",
    pcx_c_o2: "和某人之间不愉快 / 吵架 / 受伤了",
    pcx_c_o3: "一切都不顺 / 计划全泡汤了",
    pcx_c_o4: "只是心里很沉，说不出为什么",
    pcx_c_q: "哎，听到这个真难受……这样的日子真的会把人掏空。一天可以就是这样，这完全没关系。想说说今天最压在你心上的是什么吗？",
    pcx_cr1_s: "它没有像变魔术一样消失，这完全没关系。这样的日子，只需要用最少的力气度过。别和这种感觉对抗——就让这一天平静地结束吧。",
    pcx_cr2_o1: "🌬️ 一起做 5 次呼吸",
    pcx_cr2_o2: "✍️ 写 3 句话",
    pcx_cr2_s: "脑子快要溢出来的时候，最好的办法是把注意力转移到身体上。我们可以一起慢慢呼吸 5 次，或者你可以在这里写 3 句话，把脑子里转的东西都写出来——把它们释放掉。",
    pcx_cr3_s: "一定会好起来的。你以前也经历过难熬的日子，也都挺过来了，今天也快结束了。你今天已经尽力了，这就完全足够了。抱抱！🤗",
    pcx_cr_me: "嗨，我回来了... 还是很难受 / 变得更累了",
