    faq_a_dictation: "可以——点快速便签或笔记本书写页角落的 🎤 麦克风，然后说话：说的话会实时以应用的语言写下来。再点一次停止。第一次使用时，浏览器会请求麦克风权限。适用于 Chrome / 安卓和 iPhone 上的 Safari。 在电脑上需要麦克风，以及 Chrome、Edge 或 Safari 这类浏览器——如果缺了什么，提示会准确说明。",
    faq_q_dictation: "可以说话代替打字吗？",
    faq_a_secret_room: "New Me 里一个只属于你的房间——一座藏在巨树里的小屋。每次看到一面墙，用箭头（或滑动）转身。在 3 个不同的日子给一餐打 ✓ 后会得到第一把钥匙，它会打开房门——连同整个房间：电脑、游戏、唱片机、里面有图书馆的书架和猫。之后，每完成一个挑战（本周挑战也算）就会得到一把钥匙，打开下一个地方：星空屋顶、面朝大海的门廊、吉他和日记、呼吸室、有瑜伽的森林小路、瀑布和屋顶上的惊喜——第 8 个挑战会从海上带来一个瓶子，里面装着来自过去的信。有东西打开时，会有箭头为你指路。游戏机底部的小门也会打开——目前它后面的小柜子是空的。在星空屋顶上，被点到的星星会像流星一样落下，猫坐在坐垫上。",
