    faq_a_reminders_one_place: "每条提醒只来一次、只在一个地方。如果应用正在你面前打开着（电脑、iPad 或手机），提醒就显示在那里；否则只以通知的形式发到手机。在任何地方点「✅ 完成了，谢谢！」或「知道了！」，所有设备上都会关闭，而且不会再来。「还没有」会稍后提醒：每5分钟再来一次，每次只在一个地方。在列表里给任务打 ✓ 也算完成。如果希望电脑和平板也收到通知，请在 设置 > 通知 里打开「也在电脑和平板上」。",
    faq_q_reminders_one_place: "为什么提醒只来一次，而且只发到手机？",
    reminder_all_devices_hint: "默认情况下，每条提醒只来一次、只在一个地方：手机，或者你面前正打开着应用的设备。在一个地方点「完成」或「知道了」，所有地方都会关闭。",
    reminder_all_devices_label: "也在电脑和平板上",
    myday_water_info: "8 杯中杯 / 小杯的水平均约为 2 升",
    faq_a_good_things: "晚上（18:00 起），日期下方会出现一个小按钮：写下今天发生的最多 3 件好事 —— 一件就够了。它们会被保存，在「之前的日子」里可以看到以前写的内容。「今晚先不写」会把它隐藏到明天，也可以在 设置 > 个性化与日历 中完全关闭。",
    faq_a_home_countdown: "在日历里给活动标上 ⭐（活动列表中旁边的星星）。未来 100 天内最近的带星活动会显示在日期下方 ——「还有 3 天 · 妈妈的生日」「明天 · …」或「今天 · …」。点一下即可跳到日历中的那一天。",
    faq_a_home_streak: "它记录您连续多少天至少有一个 ✓ —— 我的一天、我的日常、我的目标或 New Me 中的任何一项都算。从 2 天开始显示。今天还没有 ✓ 时，连续记录并没有中断 —— 还有一整天。如果中断了，它只会安静地消失，不会有任何责备。",
    faq_a_home_weather: "在 设置 > 个性化与日历 中开启「主屏幕天空中的天气」并允许定位。之后主屏幕的天空会显示您所在地的真实天气——太阳（夜里是月亮和星星）、云、雨、雪、雷雨或雾——在所有主题中都会显示，大约每 40 分钟更新一次。大致位置（四舍五入到约 1 公里）只保存在您的设备上，并通过我们的服务器向 MET Norway 查询。默认关闭。开关下方会显示现在外面的天气——例如 ⛅ 多云间晴，所以天空里会同时有太阳和云。",
