    faq_a_home_focus: "点击主屏幕顶部的 ◎：除了现在这一件事 – 这个时间要做的事，或今天清单上的下一件事 – 以及一个大大的 ✓ 和快速笔记，其他都会隐藏。打 ✓ 后会出现下一件事。点击顶部的「专注模式 ✕」即可恢复一切。",
    faq_a_home_search: "打开菜单 ☰——搜索就在最上面。输入至少 2 个字：结果来自你的笔记、购物清单、日历、食谱、笔记本（标题和页面文字）、目标、表格和书籍，按类型分组——点一下就能直接跳过去。",
    faq_a_my_day: "「我的一天」把以前的「今日一瞥」和「我的日常」合并成一条时间线。在主屏幕底部可以看到已完成多少、现在或接下来要做什么（可快速打 ✓），标题旁边还可以 +1 喝一杯水。点击（或向上滑动）即可打开整天：最上面是没有时间的事项，然后按小时排列所有内容 – 日历中的任务、活动和会议、每周固定时段、今天的日常、目标的小小一步和 New Me 餐食 – 还有一条「现在」线。可以按任务、日常或会议与活动筛选。这里的 ✓ 和其他地方（我的日常、我的目标、日历）是同一个 ✓，还会让角落里的雏菊开花。「编辑日常」会打开「我的日常」（菜单里也有），「＋ 添加到今天」可以添加今天的任务。点一下\"我的一天\"标题（或顶部的小横条）就会再次关闭。",
