    faq_a_table_shopping_link: "在关联购物清单的 ✓ 列里（比如“本周饭菜”中的“食材已备”），每一行还没勾选的旁边都有一个 🛒。点一下就加入购物清单——只加一次，不会重复。在这里打 ✓，它就会从清单里移除；在清单里删掉它，这里也不再显示“已在清单中”；在清单里标记为已买，这里的那一行会自动打 ✓。任何 ✓ 列都可以在列设置里关联或取消关联。",
