    bag_tasks_general: "📝 一般任务",
    faq_a_bag_pockets: "每个笔记本、表格和任务都可以移到其他口袋：打开它的窗口（笔记本里的 🎨、表格里的 ✏️，或点一下任务），然后选择口袋。要修改口袋的名称、图标或颜色，打开口袋并点名称旁边的 ✏️。删除口袋会删除里面的所有内容，所以想保留的东西请先移走。新包自带的示例也一样 – 随时可以修改或删除。",
    faq_a_my_bag: "“我的包”把你的笔记本、表格和任务放在一起。每个口袋是生活的一个领域 – 家、家人、工作、一次旅行 – 有自己的名称、图标和颜色。点一个口袋，它会像活页夹一样打开：里面的所有内容都在同一页上，侧边的彩色分隔页可以跳到其他口袋。＋ 可以添加笔记本、表格（或由 AI 生成的表格）、任务或新口袋。筛选可以只显示笔记本、表格或任务，🔍 可以搜索所有内容。顶部的 ✅ 任务卡片对所有人免费；口袋、笔记本和表格属于高级版。",
    faq_q_bag_pockets: "怎样在“我的包”里移动或删除东西？",
