    premium_benefit_bag: "我的包 – 装着你自己的笔记本和表格的口袋",
    faq_a_goal_library: "在我的目标里点击 ＋（还没有目标时点一个主题）即可打开目标库：12 个主题——健康、体重、音乐、学习、金钱、家庭等——每个主题再分成几个方向，里面是现成的计划。每个计划按周显示里程碑（或天数挑战、计数、体重目标）以及每日小小一步。“开始这个目标”会立即创建，“先编辑”可以先随意修改，“添加到我的日常”开关会把每日一步放进日常的空闲时段（点一下时间可以换成别的时段）——在一处打 ✓，另一处也会同步打上。也可以搜索（“吉他”“考试”），“✏️ 我自己的目标”随时可选。每个主题有 2 个计划免费，整个目标库随高级版开放 ⭐。",
