    vision_goal_delete_routine_note: "它在我的日常中的项目也会一起删除。",
    faq_a_goal_small_steps: "「我的目标」中的每个目标都是一条路：已经走过的里程碑、今天发光的石头，还有终点的奖杯。可以给目标设定一个小小一步 – 每天，或每周在你选择的某一天 – 即使在难熬的日子也能做到的事，比如「轻松慢跑10分钟」。今天所有的小小一步都会出现在「我的目标」顶部和「我的一天」中，每个都能快速打 ✓；目标小路下方的「✓ 今天做了」会填满最近7天的圆点。「在通往10分的路上 · 不停步」这张便签故意一直留在顶部：我们不必完美 – 只要每天做一点点，就能向前走。",
