    gv_back: "返回",
    faq_a_food_not_fried_default: "不会。除非写明(油炸、炸、裹粉、炸鸡排、薯条……)，食物都按烤、烧烤或几乎不放油的平底锅烹调计算。「用平底锅」最多只表示少量油，不是油炸；提到烤箱或平底锅也不会改变分量。吃了油炸的?直接写出来就行(例如「炸鸡胸肉」)。",
    faq_q_food_not_fried_default: "AI会默认食物是油炸的吗?",
    faq_a_routine_nudge: "当某个项目超过 3 天没有打勾 ✓（只计算它该出现的日子），顶部会出现一张温和的卡片，询问它是否仍是日常的一部分、是否有效——也许需要改点什么才能前进：\n• ✓ 是的，继续——一周内不再问它。\n• ✏️ 修改——打开该项目进行编辑。\n• 🗑️ 移除——把它从日常中移除。\n• ✕——以后再说。\n当有超过 3 个项目在等待时（也许是去度假了），会用一张卡片一起询问：照常继续，或者改点什么——后者会打开这些项目的列表，每项都有 ✏️ / 🗑️。\n只有在 ✓ 追踪开启并在使用时，卡片才会出现。复制到多个日期标签页的同一个项目只算一个。",
    faq_q_routine_nudge: "为什么「我的日常」会问我某个事项?",
    faq_a_routine_day_tabs: "可以。在⚙️中选择「此标签的日子」——在这些日子里，「我的日常」会直接打开它，并用一个小圆点标记。以星期命名的标签(如「星期日」)会被自动识别，日期模板也会自动设置日子。标签设有日子时，关于✓的提问只统计其事项存在的日子。",
    faq_q_routine_day_tabs: "「我的日常」可以直接打开今天的标签吗?",
    faq_a_routine_add_templates: "在「我的日常」中点击➕并选择:\n• ✏️ 新的空白标签。\n• 📄 复制当前标签——复制它的所有时间和事项(不含✓记录)。复制像「星期日」这样的日期标签时，会自动建议下一个空闲的日子——这是为每天建立不同日常的最快方式。\n• ⭐ 现成模板(高级版):每天一个标签(周日至周四、周一至周五、周日至周五或整周)——空白，或每天都是当前标签的副本——以及10套带内容的现成安排:平静的早晨、夜晚与好睡眠、工作日、居家办公、学习日、训练日、规律饮食、平静的一天、陪孩子的一天和周末。之后都可以编辑。",
    faq_q_routine_add_templates: "如何在「我的日常」中复制标签或使用现成模板?",
