    reminder_ring_label: "响铃",
    calendar_event_duration_1m: "持续1个月",
    books_lookup_none: "按这个书名没找到——试试在下方输入作者名字。",
    books_lookup_try_author: "这里没有?也可以在下方输入作者名字。",
    nm_ch_morning_stretch_help: "简单 5 分钟：\n• 双臂上举，长长伸展——30 秒\n• 转动脖子和肩膀——1 分钟\n• 膝盖放松，轻轻前屈——1 分钟\n• 体侧拉伸，每侧——1 分钟\n• 四足跪姿猫牛式——1 分钟\n轻柔不痛——慢慢呼吸。",
    nm_ch_slow_meal_help: "做法：\n• 每天有一顿饭至少吃 20 分钟\n• 每口之间放下餐具，好好咀嚼\n• 开始时喝一杯水\n身体大约需要 20 分钟才感到饱——慢慢吃能让它跟上。",
    nm_ch_kitchen_closed_help: "晚上 8 点以后：\n• 水、苏打水和花草茶\n• 不吃东西、不吃零食，也不“只尝一口”\n小贴士：晚饭后刷牙是“厨房关门”的好信号。晚饭吃得晚没关系——只要 8 点前吃完。",
    nm_ch_no_soda_help: "什么算含糖饮料：\n• 汽水和可乐、冰茶、能量饮料\n• 果汁和果肉饮料——包括 100% 纯果汁\n• 加糖调味水和浓缩糖浆\n可以：水、苏打水、加柠檬或薄荷的水、不加糖的茶和咖啡。",
    nm_ch_fruit_dessert_help: "点子：\n• 撒肉桂的苹果片，或烤苹果\n• 冷冻葡萄或冷冻香蕉片\n• 草莓、甜瓜、西瓜、芒果、浆果\n• 椰枣或果干——少量\n想吃甜的很正常——只是用水果代替蛋糕或糖果。",
    nm_ch_screen_free_meal_help: "做法：\n• 每天一顿饭不看手机、电视、电脑或平板\n• 坐在桌边，慢慢吃，感受味道和饱足感\n小贴士：整顿饭期间把手机放在另一个房间，或屏幕朝下放进抽屉。",
    nm_ch_walk_after_meal_help: "做法：\n• 每天一顿饭后轻松走 10 分钟——午饭或晚饭后最好\n• 户外、走廊或绕着家里走——都算\n• 边走边打电话也算\n饭后短暂散步有助消化，让精力更平稳。",
    nm_ch_veg_each_meal_help: "点子：\n• 早餐：鸡蛋或奶酪旁配黄瓜、番茄或彩椒\n• 午餐：配一份沙拉或熟蔬菜\n• 晚上：快手切丁沙拉、烤蔬菜或蔬菜汤\n新鲜、煮熟、冷冻或做成沙拉——都算。",
    nm_ch_water_first_help: "做法：\n• 起床后马上喝一大杯水（约 300–500 毫升）\n• 在咖啡或早餐之前\n小贴士：床边放一杯水，或前一晚在台面放一瓶——自然就做到了。",
    nm_ch_cinnamon_coffee_help: "做法：\n• 在咖啡里，或打奶泡前的牛奶里，加半茶匙肉桂粉\n• 不加糖，也不加甜糖浆\n• 加奶？普通奶或无添加糖的植物奶\n什么咖啡都行——浓缩、黑咖啡、滴滤或拿铁。",
    nm_ch_lose5_month_help: "每天三件事：\n• 不超出热量预算（热量缺口）\n• 20 分钟以上的运动\n• 不吃添加糖\n这个挑战数的是天数，不是公斤——体重会按自己的节奏下降。每周在同一时间称一次，看得最清楚。",
    nm_ch_menu_21_help: "当天怎么打勾：\n• 菜单里至少 3 顿打 ✓——菜单不到 3 顿就全部打 ✓\n• 计划好的自由餐算一顿\n• 更换过的餐（🔄）也算——它仍然来自菜单\n✓ 够了，当天会自动打勾。",
    nm_ch_no_snacking_14_help: "可以的：\n• 菜单里的正餐和加餐，按时吃\n• 饮品：水、苏打水、茶、咖啡\n算额外的：做饭时试吃、吃完孩子剩下的、两餐之间一把坚果或一块饼干。\n小贴士：两餐之间饿了？先喝水，等 10 分钟——下一餐很快就到。",
    nm_ch_home_food_14_help: "什么算：\n• 在家做的一切——哪怕是三明治、鸡蛋或沙拉\n• 带去上班或上学的家里饭菜\n不算：外卖、打包、餐厅、快餐和在外面买的现成菜。\n计划好的自由餐可以。",
    nm_ch_no_fried_14_help: "什么算油炸：\n• 薯条和薯片、炸肉排、炸丸子（法拉费）、炸鱼\n• 甜甜圈、土豆饼和油炸零食\n• 一切用大量油炸的食物\n替代：烤箱、烤架、空气炸锅，或放一勺油的平底锅。\n小贴士：自制烤箱版肉排是很棒的替换。",
    nm_ch_sport_14_help: "什么算（20 分钟以上）：\n• 快走、跑步、骑车、游泳\n• 健身房、普拉提、瑜伽、跳舞、居家训练\n• 爬楼梯或和孩子一起活跃地玩——连续 20 分钟\n在「锻炼记录」中记录的 20 分钟以上锻炼会自动打勾；否则就在这里打勾。",
    nm_ch_deficit_14_help: "怎么算：\n• 每日预算 = 计划（1,300 或 1,500）+ 当天记录的运动消耗\n• 吃下的都算：菜单、饮品，以及在每日饮食记录中添加的内容\n• 圆环保持在预算内，当天就算完成\n小贴士：计划好的自由餐没问题——当天其余时间吃得清淡些就好。",
    nm_ch_no_carbs_7_help: "什么算碳水：\n• 面包、皮塔饼、小面包、饼干和米饼\n• 意面、米饭、古斯米、碎小麦、藜麦和面条\n• 土豆、红薯和玉米\n• 早餐麦片、燕麦和格兰诺拉\n• 糕点、蛋糕、饼干、糖和甜食\n• 大量豆类（鹰嘴豆、扁豆、豆子）和果汁\n代替碳水——多加蔬菜和蛋白质：鸡蛋、鸡肉、鱼、金枪鱼、茅屋奶酪、豆腐。\n清单只是参考——具体去掉什么，由自己决定。",
    nm_ch_no_sugar_5_help: "要避免的：\n• 白糖和红糖、蜂蜜、糖浆和椰枣糖浆\n• 糖果、巧克力、蛋糕、饼干和冰淇淋\n• 含糖饮料和果汁\n• 加糖酸奶和早餐麦片\n可以：水果、无添加糖的乳制品、不加糖的咖啡和茶。\n小贴士：看看配料表——糖也藏在酱料和番茄酱里。",
    nm_ch_help_btn: "具体什么算？",
    faq_a_new_me_plans: "New Me 有两种方案：每月 $11.99，或一次性 $99.99 终身使用。按月方案可随时在 ⚙️ 设置 > 💳 管理订阅 中取消——New Me 会一直开放到已付费月份结束。也可以在那里改为终身，按月订阅随即自动停止，不会重复扣费。在按月方案推出之前购买的 New Me 仍为终身。两种方案都包含高级版的全部功能。",
