    nm_gift_title: "你的礼物",
    faq_a_new_me_letter_gift: "在 New Me 开始时（或之后在挑战页面中），可以写一封给未来自己的信。封存后，在它打开之前都无法阅读或编辑：它会在秘密房间里那个来自大海的瓶子中打开，或在完成全部 20 项挑战时打开——那时还有一份礼物在等你。",
    faq_q_new_me_letter_gift: "什么是来自过去的信？",
    faq_a_new_me_challenges: "🏆 挑战里有 20 个挑战：10 个大挑战（比如 5 天不吃糖、一周不吃碳水，或一个月减 4 公斤——每天热量缺口、锻炼、不吃糖）和 10 个小挑战——为期一周的小习惯，比如无糖肉桂咖啡。选择挑战时会问什么时候开始：今天、明天、下周或其他日期。一个大挑战和一个小挑战可以同时进行。进行中的挑战显示在菜单最上方和「我的一天」里，可以给当天打 ✓。挑战每一周有一个不会中断挑战的休息日（🍕），没打勾的日子算作休息日——今天和昨天都可以打勾。有些日子会自动打勾：在「锻炼记录」里记录 20 分钟锻炼，或菜单里的餐打上 ✓。每项挑战都有一个 ⓘ，说明具体什么算数（例如完整的碳水清单）——在挑战里，也在「我的一天」中挑战的旁边。在它们下面，🌱 个人成长 里还有 48 个为期一周的小挑战（不计入这 20 个）——见“什么是本周挑战？”。",
    faq_q_new_me_challenges: "New Me 里的挑战怎么用？",
    nm_letter_too_short: "再多写几个字吧 🙂",
