    nm_tile_challenges: "挑战",
    faq_a_workout_calories: "会。每次运动都会估算消耗的热量 – 根据类型、时长和最近一次体重（跑步和骑行在填写距离时还会考虑速度）。它显示在运动列表和月度汇总（消耗）中，并加入当天的热量预算：在每日饮食记录、卡路里与体重指标以及 New Me 的圆环中。这是估算值，所以带有 ~。",
    faq_q_workout_calories: "运动会计入当天的热量吗？",
    faq_a_new_me_flexible_menu: "可以。在问卷和设置里选择一天吃几餐——2 餐 + 1 次加餐 / 2 餐 + 清淡晚餐 / 2 餐 + 1 次加餐 + 清淡晚餐——餐卡上的 ➖ 可以去掉一餐（至少保留 3 个）；「放回菜单」可以放回来。无论怎样，一天的热量都不变：去掉的部分会分给其他几餐，每餐下方会显示多了多少以及可以加些什么。点餐上的 ✏️ 编辑会打开它的文字——随意修改（比如不要面包或多一个鸡蛋），AI 会重新计算热量和蛋白质。🔄 更换提供菜单选项、⭐ 已保存和 ✨ 写下来；每次改动都可以只限今天或从现在起。「全天」最后还有 ➕ 添加食物——写下菜单以外吃的东西，AI 会计算并加到今天（✕ 删除）。",
    faq_q_new_me_flexible_menu: "在 New Me 中可以改变用餐次数，或吃自己的餐点吗？",
    daily_calorie_mini_burn: "+🔥 运动 {amount}",
    calorie_burn_line: "🏃 运动消耗 {amount} 千卡 – 已加入当天预算（{budget}）",
    sport_total_kcal: "消耗",
