    nm_burned_line: "运动消耗 {n} 千卡——已加入今天的预算",
    faq_a_calendar_goals_reading: "会。在月度概览中点按某一天，还会在单独的“🎯 目标与阅读”分组中显示当天来自目标和书籍的任务：天数挑战的每日任务、称重或计数提醒，以及“📖 读 N 页”。今天的任务可以直接在那里勾选，就像在我的一天中一样；其他日子只供查看——过去的日子显示完成了什么、读了多少页，未来的日子显示计划。为了让日历保持清爽，只有特殊的日子才有小标记：目标日期上有🎯，计划读完一本书的那天有📖。",
    faq_q_calendar_goals_reading: "目标和阅读会显示在月度概览中吗？",
    faq_a_meetings: "在日历视图中点按＋（在月度概览、所有事件或会议中），并在顶部选择🤝 会议——旁边的✅ 任务和📅 事件照常使用。会议有开始时间，也可以填写结束时间、和谁开会、地点或链接（地址、Zoom、Meet…）以及备注。会议会显示在🤝 会议卡片中——一本按周排列的纸质手账，每天一行；用箭头切换周，点按会议即可编辑。地点会在地图中打开，通话链接会有一个“🔗 加入”按钮。会议还会带着时间显示在月度概览和我的一天中，像其他事件一样有提醒，并连同结束时间、地点和详情同步到 Google Calendar。 在「我的一天」中，会议也会显示和谁开会(👤)，重复的会议也可以只持续1个月。",
    faq_q_meetings: "如何添加会议？在哪里查看我的会议？",
