    apptour_nb_inside_text: "每个口袋都像活页夹一样打开，彩色分隔页可以在口袋之间切换。笔记本的页面真的会翻动，表格的列由你来选。",
    apptour_nb_inside_title: "包里面",
    faq_a_recipe_to_preset: "可以。打开食谱，点“⭐ 加入已保存的食物”。名称、每份的卡路里(如果没设份数就是总量)和食材都已填好，还配上合适的类别 – 检查一下，改你想改的，然后保存。之后在每日饮食记录和快速添加 🍎 里一点就能用。",
