    faq_a_my_notebooks: "笔记本放在“我的包”的口袋里，每本都有你亲自设计的封面 – 颜色、图案和贴纸。里面是奶油色的纸页，会像真正的笔记本一样翻动：左右滑动，或点底部页面条里的某一页；页面条里的 ＋ 可以添加新页面 – 横线（书写）、方格（数学和草图）、空白（画画）或清单。在画画的页面上，工具浮在页面底部：钢笔、荧光笔、扁头荧光笔和橡皮擦，颜色圆点用来选颜色和粗细，还有撤销和贴纸。🔍 打开带搜索的目录，🔖 标记笔记本打开时所在的页面，⋯ 里有封面与详情、重命名页面、清空画面和删除页面。“我的包”顶部的 ✅ 任务卡片会打开你的待办清单，大任务可以用 🪄 智能拆分。笔记本属于高级版；任务清单免费。",
