    faq_a_google_calendar_reconnect: "通常是因为 Google 终止了应用的访问权限 – 例如过了一段时间、更改了密码，或者在您的 Google 账户中移除了访问权限。出现这种情况时，设置中会显示一条警告，提示与 Google Calendar 的连接已过期，并附有「🔄 重新连接」按钮（打开应用时也会出现一条简短的提示）。点击该按钮并再次批准 – 在此期间您添加的所有内容都会在一两分钟内发送到 Google，所以不会丢失任何内容。",
    faq_q_google_calendar_reconnect: "为什么我添加的事件没有同步到 Google Calendar？",
    google_calendar_reconnect_toast: "Google Calendar需要重新连接 – 可以在设置中修复 ⚙️",
    settings_google_calendar_reconnect_btn: "🔄 重新连接",
    settings_google_calendar_reconnect_warning: "⚠️ 与Google Calendar的连接已过期，新事件无法发送到Google。请重新连接 – 在此期间添加的所有内容都会在连接后立即发送。",
    apptour_m_books_link: "设置读完期限后，「我的一天」中会添加每日阅读任务；读完的书还可以计入「我的目标」中的阅读目标。",
    apptour_m_books_text: "温馨的阅读角：想买、待读、在读和读过的书 – 配有进度条、读完期限，还有摆满读完之书的书架。",
    faq_a_books_deadline: "对于在读的书，在详情中设置「读完期限」（或点击卡片上的 📅）。卡片会显示剩余天数和每天需要读的页数，「我的一天」中会出现每日任务，例如「📖 读 15 页」– 勾选后这些页数会加到书上，取消勾选则会扣回。这个数字在每天开始时根据你在书中读到的位置确定。要让书计入目标，点击「🎯 关联阅读目标」，然后从「我的目标」中选择一个「计数到目标值」目标 – 每读完一本书就 +1，把书移回去则会减掉。把页码改小，或者只是试着点了「读完了 🎉」，任务都不会消失：改小的页码算作修正而不是阅读；从「✅ 读过」移回「📖 在读」的书会回到原来的页码（如果不知道原来的页码，应用会问你现在读到第几页）。",
    faq_q_books_deadline: "读完期限、每日阅读任务和阅读目标是怎么运作的？",
    faq_a_books_what: "在菜单的「清单」中打开「📚 阅读角」。共有四个标签页：🛒 想买、📚 待读、📖 在读和 ✅ 读过。点击「+ 添加图书」并输入书名 – 如果在 Open Library 中找到这本书，点一下就能填入封面、作者和页数（找不到的话会得到一个彩色封面）。点一下就能让书进入下一步：「买到了 ✓」、「▶ 开始阅读」和「读完了 🎉」。阅读时更新你读到的页码（或点击 +10 / +25），就能看到进度条和你的 🔥 阅读连续记录不断增长。读完的书会摆在木质书架上，附有你的 ⭐ 评分和你喜欢的一句话 – 点击一本书即可再次打开。按书名找不到?输入作者名字就会显示该作者的书——Open Library 找到的结果少时,也会在 Google Books 中搜索。",
