    faq_a_goal_tasks_peek: "共有三种：进行中的天数挑战的每日任务（例如「不吃碳水」）– 在挑战完成前每天都会出现，在那里打 ✓ 也会在目标中勾选当天（反之亦然）；📅 你安排好的目标里程碑 – 在对应日期出现，也会出现在日历中；👣 其他目标的小小一步 – 在添加或编辑目标时设定（每天，或每周在你选择的某一天）。它们和「我的目标」顶部「今天的小小一步」中的是同样的步伐，每个都带有所属目标的图标。当天记录一次 +1，小小一步就会自动勾选（如果小小一步就是称重本身，记录体重也会自动勾选）。",
