    faq_a_goal_days_challenge: "在「我的目标」中点击 ＋（或现成的示例「🔥 8天」），选择「📆 天数挑战」，输入天数，并添加每天要做的事（例如「步行30分钟」「按我的菜单吃饭」）。每天在挑战小路的下方勾选当天的任务 – 全部勾选后这一天就算完成，小路前进一块石头，🔥 连续记录随之增长（没有每日任务时，只有一个「✓ 今天做到了」按钮）。任务旁边的 🔁 按钮会把它添加到「我的日常」中你选择的时间：在那里打勾，目标里也会同步打勾，反之亦然。普通目标的里程碑也可以用同样的方式添加到「我的日常」。",
