    vision_focus_ribbon: "🎯 本月目标",
    vision_tagline: "大目标，小步伐。",
    faq_a_app_tour: "导览只会在你第一次进入时自动打开一次。它先列出各个部分——点一下就能直接跳到那里——然后介绍应用的每个部分（主屏幕、AI 助手和菜单里的每一项）以及设置的五个分组，每个都有简短说明，还会带你看看其中一些的内部（比如一条示例目标路径、背包和 Google Calendar）。“继续”前进，“返回”后退，“跳过这一部分”跳到下一部分，✕ 关闭导览。随时可以在 设置 > 帮助与使用 > 应用导览 里重新观看，并从上次停下的地方继续。 “继续”和“返回”始终在屏幕底部的同一位置，在电脑上也可以用键盘的方向键。",
    faq_q_app_tour: "如何再次查看应用导览？",
    apptour_done_text: "有问题吗？设置中的「帮助和常见问题」能解答一切，这个导览也随时可在「帮助与使用」中找到。",
    apptour_done_title: "就是这些！🎉",
    apptour_flow_recurring: "分期付款和自动转账",
    apptour_flow_weight: "体重",
    apptour_flow_calories: "今日卡路里",
    apptour_flow_calendar: "日历",
    apptour_connect_text: "在一处的操作会自动更新到其他地方：",
    apptour_connect_title: "一切都是相通的",
    apptour_s_support_text: "帮助和常见问题、联系我们、分享应用，还有这个导览，随时可看。",
    apptour_s_account_text: "高级版、密码、个人PDF报告、Google Calendar同步和删除账户。",
    apptour_s_notifications_text: "提醒通知及其提示音。提醒中的「⏰ 还没有」就像闹钟的贪睡功能：每5分钟再提醒一次。",
    apptour_s_personalization_text: "国家/地区、每天的正餐和零食数量、财务月的开始日，以及主屏幕上显示的内容。",
    apptour_s_appearance_text: "语言、浅色或深色模式、主题、字体、文字颜色、无障碍和显示大小。",
    apptour_m_style_text: "这个按钮可把菜单切换为大方块，也能切换回来。主屏幕上只会显示其中一种。",
    apptour_m_style_title: "列表还是方块",
    apptour_m_receipts_link: "把某个分类导出为PDF，或用 🧮 按年份汇总全部。",
    apptour_m_receipts_text: "保存带照片的发票和收据，家庭或商业用途皆可。",
    apptour_m_budget_link: "分期付款和自动转账（支持从Excel导入）、自定义分类，以及设置中的预算重置日。",
    apptour_m_budget_text: "按分类记录支出和收入，并显示每月余额。",
    apptour_m_steps_text: "每天的步数。",
    apptour_m_sport_link: "「我的日常」中的习惯可以自动在这里记录锻炼。",
    apptour_m_sport_text: "一周的锻炼计划，并按类型、时间和距离记录锻炼，还能附上照片。",
    apptour_m_water_text: "对照每日目标，记录喝了多少水。",
    apptour_m_calories_link: "体重记录也在这里，与New Me以及「我的目标」中的体重目标共享。",
    apptour_m_calories_text: "对照目标的每日、每周和每月卡路里统计。",
    apptour_m_meals_link: "已保存的餐食、食物列表和AI估算；New Me、快速添加和饮品也计入这里。",
    apptour_m_meals_text: "逐日记录每餐的卡路里和蛋白质。",
    apptour_m_recipes_link: "用AI助手中的「📷 照片」扫描写好的食谱。",
    apptour_m_recipes_text: "按分类整理的食谱，带照片、卡路里和份数。",
    apptour_m_goal_link: "可以自动跟踪体重或已完成的任务。",
    apptour_m_goal_text: "每月一个目标，配有进度条，达成时还有奖励。",
    apptour_m_shopping_link: "从「快速笔记」一秒添加物品。",
    apptour_m_shopping_text: "购物清单，在商店里边买边勾选。",
    apptour_m_notes_link: "把笔记拖到「今天」「明天」或其他日期，即可变成任务；删除的笔记会留在 🗑️ 存档中。",
    apptour_m_notes_text: "笔记和想法集中在一个列表里。",
    apptour_m_tables_link: "AI助手可以自动设计表格。",
    apptour_m_tables_text: "个人表格：礼物、剧集、清单等，支持文本、数字、选择、日期和 ✓ 列（高级版）。",
    apptour_m_study_link: "✅ 任务卡片里的 🪄 智能拆分，会把大任务拆成日历里的小步骤。",
    apptour_m_study_text: "你的包：生活的每个领域一个口袋 – 里面有笔记本、表格和任务。",
    apptour_m_vision_link: "点里程碑上的 📅 即可把它放进日历；小小一步和天数挑战的任务会出现在「我的一天」中，进度也可以跟随数字或体重。",
    apptour_m_vision_text: "你的目标是一条条由小小一步组成的路 – 今天的步伐就在最上面。我们进去看看 👇",
    apptour_m_myweek_link: "可与Google Calendar同步（在设置中）。",
    apptour_m_myweek_text: "月历、带提醒的每周重复任务，以及所有有日期的活动。还有一本记录本周会议的纸质手账🤝。",
    apptour_m_newme_link: "一切都计入「每日饮食记录」和「我的一天」；体重与「卡路里与体重指标」共享。",
    apptour_m_newme_text: "魔法游戏世界里的 1,300 / 1,500 卡路里饮食计划：带 ✓ 的今日菜单、三种更换方式 – 从菜单、从已保存的餐食，或把吃了什么写给 AI，由它算出卡路里 – 购物清单、用餐提醒，以及包含成就、围度和照片的进步旅程。还有 🏆 20 个挑战 – 终点有礼物 – 以及本周挑战。",
    apptour_ai_table_text: "描述需要的表格，AI会设计好列（高级版）。",
    apptour_ai_photo_link: "保存在「我的食谱」中。",
    apptour_ai_photo_text: "拍下写好的食谱，AI会自动填好新食谱。",
    apptour_ai_schedule_link: "它们会显示在日历和「我的一天」中。",
    apptour_ai_schedule_text: "用平常的话描述计划，一次性或重复的都行，直接进入日历。",
    apptour_ai_food_link: "直接计入「每日饮食记录」和今日总计。",
    apptour_ai_food_text: "输入吃了什么，卡路里会自动估算并记录。",
    apptour_newme_short_text: "打开 New Me – 今日菜单就在主界面上。",
    apptour_ai_link: "上面的小「1」徽章是每日「今天最重要的事情」提醒。",
    apptour_ai_text: "用简单的话写下来，助手会搞定剩下的：记录卡路里、把计划放进日历、从照片读取食谱、还能做表格。",
    apptour_quicknote_link: "📝 和 🛒 打开完整列表；🍎 把已保存的餐食记录到「每日饮食记录」。",
    apptour_quicknote_text: "快速记下内容，存入「笔记」或直接加入「购物清单」。",
    apptour_routine_link: "习惯可以自动在「锻炼记录」中记录一次锻炼。",
    apptour_routine_text: "按小时安排的每日作息，分标签页（孩子、学习、工作…）。每天打 ✓，养成习惯、积累连续记录；📅 显示整个月。",
    apptour_premium_text: "解锁完整的 AI 助手、主题、字体、我的包等更多功能。",
    apptour_note_text: "一整周的便利贴。里面的 ⚙ 齿轮可添加1–3行勾选清单，并更改颜色和样式。",
    apptour_peek_link: "来自AI、日历、目标步骤和Google Calendar的任务都显示在这里，还有今天的卡路里 🔥 和 🎯 本月目标。",
    apptour_peek_text: "今天的一切都在一处 – 任务、会议、日常和小小一步排在同一条时间线上。直接在这里打 ✓。",
    apptour_date_text: "点击即可快速查看月历，还能立即添加内容。",
