    table_select_option_delete_title: "删除选项",
    faq_a_other_manual_option: "凡是从选项列表中选择的地方，都有「✏️ 其他」 - 选择它，然后输入您需要的内容即可。在带有选择列的表格中(例如礼物表格中的「关系」)，点击单元格，选择「✏️ 其他」，输入值(例如「侄子」)，然后点击添加 - 它会被保存为该列的新选项，下次就会直接出现在列表中。该列表中每个选项旁边的小 × 可将该选项从列中删除。选择表格图标时有许多图标可选(包括彩色便利贴)。已保存的食物分类、食谱分类、定期支出分类(保存为新的个人分类)以及「我的目标」中的目标分类也都是同样的用法。",
