    faq_a_receipts_total: "在“发票 / 收据”页面，点按 🧮“所有收据总计”。选择起止年份（默认从最早的收据到今年），点按“计算”，即可看到两个类别合在一起的总额（家庭支出和商业支出），以及收据数量和每个类别各自的总额。",
