    faq_a_quick_note_apple: "便签窗口中 📝 和 🛒 旁边的 🍎 是一个快捷方式，可将已保存的餐食快速记录到今天的每日饮食记录中。它默认开启 - 如果不需要，可以在设置 > 个性化与日历中关闭(“在便签窗口中显示 🍎 已保存餐食快捷方式”)，之后随时可以在同一处重新开启。",
    faq_q_quick_note_apple: "便签窗口中的 🍎 是什么？可以隐藏吗？",
    settings_quick_note_apple_label: "在便签窗口中显示 🍎 已保存餐食快捷方式",
    faq_a_vision_board_today: "在「我的目标」中，目标小路的下方（「计划」里），点击里程碑旁的 📅 并选择日期。你也可以开启「🔁 每周重复，直到完成」– 这样它会每周在同一天再次出现，直到你勾选一次为止。该里程碑会在当天出现在「我的一天」和日历中（如果已连接 Google Calendar，也会出现在那里），按钮上会显示安排的时间。在任一处打 ✓，另一处也会同步勾选，目标的小路也会向前推进。再次点击 📅 可以更改日期或将其从日历中移除。从日历中删除一次性任务，也会从目标中删除该里程碑；删除每周提醒中的某一周，只会移除那一周。",
