    nm_drink_name_ph: "饮品（例如：果汁）",
    nm_drinks_hint: "只需输入饮品名称——卡路里会自动计算，数值也可以修改。",
    nm_slot_drinks: "饮品",
    faq_a_new_me_tracking: "点 New Me 顶部的下一个任务，再点 ✓ 我吃了，就能把下一餐标记为已吃——每餐都带 ✓ 的完整菜单在侧边的“全天”中，今天的餐食也会显示在主屏幕的“我的一天”里——在那里点一下某一餐（或把鼠标移到上面），就能看到具体要吃什么，还有 ✓ 和“更换”。一切都与每日饮食记录同步：计划中的餐食、饮品，以及你在其他地方添加的内容（例如通过快速添加加入的咖啡），都会在 New Me 和“我的一天”中合并计算——已经输入的内容不会被覆盖，取消 ✓ 只会移除 New Me 的部分。今天的餐食全部勾选后，会有一个小小的庆祝。在“饮品”里记录当天的饮品——加起来最多~150 千卡，也就是大约 3 杯、每杯最多~50 千卡。只要输入饮品名称，热量就会由 AI 自动填写。两行咖啡/茶还有一个“加奶吗？加多少？”栏（例如“一点”或“50 毫升”），计算会随之更新；数字在添加前后都可以修改。填好名称和热量的饮品，在你继续操作时就会自动保存——点“添加”是可选的。点饮品旁的 ☆，可以把它存为常喝饮品——常喝饮品会以按钮的形式出现在饮品卡片顶部，点一下就能加入当天。⭐ 会把一餐存为已保存的餐食。“每日表格”会显示你吃了什么，以及热量和蛋白质。主屏幕顶部专注模式旁边的小 💎 可以直接打开它。热量和蛋白质数值是 AI 估算，可能存在误差。 没吃完？在已勾选的餐食下方，“没吃完？”可以减去份量的四分之一、一半或四分之三——或按你写下的内容计算减去——当天的热量也会随之更新。",
    faq_q_new_me_tracking: "New Me 中的 ✓、更换和卡路里是如何运作的？",
    faq_a_new_me_what: "New Me 是一个独立的每日菜单方案，有两个现成计划——1,300 或 1,500 千卡——由 2 顿正餐和 2 份加餐组成，每项有 3 个选择。它包含高级版的全部功能。价格：每月 $11.99（随时可取消）或一次性 $99.99 终身使用。在菜单中点按 💎 New Me 即可打开。开始前有一份简短问卷，首先需要接受一份医疗免责声明。本方案仅为一般信息，不能替代医生或临床营养师。",
