    nm_disclaimer_p4: "4. 责任限制。用户使用本计划的风险由其自行承担。对于因使用本计划、其菜单或所显示的卡路里及蛋白质数值（均仅为近似估算值）而产生的任何直接或间接损害，无论是否涉及健康，本应用的开发者和运营者均不承担任何责任。",
    nm_disclaimer_p3: "3. 未经医疗许可，本计划不适用于：孕妇或哺乳期妇女、未满 18 岁的未成年人、目前或曾经患有进食障碍的人士、患有慢性疾病或基础疾病（包括糖尿病、心脏、肾脏或肝脏疾病）的人士，以及需定期服用药物的人士，但已获得主治医生明确许可的除外。",
    nm_disclaimer_p2: "2. 计划选择。选择 1,300 卡路里计划或 1,500 卡路里计划，完全由用户自行决定并自行承担责任。建议在开始任何限制热量的饮食之前咨询医生或临床营养师。",
    nm_disclaimer_p1: "1. 仅供一般参考。New Me 计划及其菜单提供的是一般性营养信息，不构成医疗、营养或其他任何专业建议，亦不能替代医生或持证临床营养师提供的咨询、诊断或治疗。在进行任何饮食调整或开始体育活动之前，应当咨询医生。",
