    faq_a_categories_menu: "应用的菜单有两种显示方式，顶部只显示一个按钮：☰ 列表（默认）或 ▦ 大方块 - 规划与日历、清单、目标与进度、营养与指标、运动以及收支；点击一个方块查看其中的内容，然后点击您需要的项目。要切换，请打开菜单并点击顶部的小按钮：列表菜单中的 ▦ 切换为方块，方块菜单中的 ☰ 切换回列表。方块菜单中还有一个 ⚙️ 按钮，用于打开设置。您的选择会被保存，并在您的所有设备上生效。",
