    faq_q_calorie_monthly_view: "如何查看整个月的卡路里历史记录？", faq_a_calorie_monthly_view: "卡路里与体重指标中有一个带日历的「月度视图」卡片 - 每天只要记录了饮食就会显示一个圆点，网格上方会显示该月的每日平均值。点击任意一天即可查看当天具体吃了什么以及总量。如果在设置中下载个人报告（PDF）时勾选了卡路里与体重指标部分，同样的明细也会包含在内。",
    faq_q_calorie_stats_total_vs_average: "卡路里与体重指标中的每周/每月数字是总数还是平均数？", faq_a_calorie_stats_total_vs_average: "两者都是 - 大数字是当前日历周/月内所有记录的总和，下面的小字则是每日平均值。平均值只按您实际记录过内容的天数来计算，而不是按7天或整月计算 - 完全没有记录的一天会被直接跳过，不会算作0，也不会拉低平均值。",
    faq_q_weight_note: "我可以给体重记录添加备注吗？", faq_a_weight_note: "可以 - 在定期体重记录（位于营养与指标 > 卡路里与体重指标底部的 ⚖️ 下）中，体重/日期输入框旁边有一个可选的备注字段。您可以用它添加说明，比如\"运动后\"或\"晨起称重\" - 它会显示在历史记录列表中该条记录的旁边。",
    faq_q_quick_note_shopping_list: "快速笔记可以直接添加到购物清单吗？", faq_a_quick_note_shopping_list: "可以——在主屏幕中间的书写行里，点开头的 📝：它会变成 🛒，写的内容会直接进入购物清单，不经过笔记。",
