    nutrition_daily_masthead_title: "📰 THE NUTRITION DAILY", nutrition_daily_masthead_subtitle: "您的每日营养、精准与生活方式杂志",
    nutrition_daily_article1_title: "📰 称重之谜——什么时候称什么？",
    nutrition_daily_article1_intro: "最推荐、最准确的记录方式是在烹饪前(生的状态)称量食物——从肉类到米饭、意面、土豆和蔬菜都一样。",
    nutrition_daily_article1_why: "为什么要在烹饪前称重？生食的数值是固定的。烹饪只会改变食物的液体含量(吸水或蒸发)，所以提前称重可以让你随意烹饪，甚至混合食材(比如做肉丸或炖菜时)也不会失去准确性。",
    nutrition_daily_article1_portion_tip: "分份小贴士：已经提前称好并计算了整锅的量？熟食的重量就不再重要了！只需按计划的份数把成品平均分配即可！",
    nutrition_daily_article1_after_note: "更喜欢烹饪后称重？如果您的生活方式更复杂，需要在食物做好后在盘子里称重——这也完全没问题！只需确保在数据库中选择对应的选项(比如「煮熟的白米饭」而不是「生米」)。💡",
    nutrition_daily_article2_title: "📰 今天超出目标了？别有压力！",
    nutrition_daily_article2_body: "超出目标了？在增重过程中吃得有点少，或者在减重过程中吃得有点多？深呼吸——一切都没问题。您的身体不是每日计算器——它是根据长期的每周平均值运作的。单日的偏差是这个过程中完全自然的一部分。没有必要「补偿」、挨饿或在下一餐强迫自己调整。只需继续正常的日常安排。长期的一致性才是真正的秘诀。",
    nutrition_daily_article3_title: "📰 在外用餐？像专业人士一样记录",
    nutrition_daily_article3_intro: "餐厅、披萨店和汉堡店总是很有趣的体验——但要怎么记录一道不是自己做的菜呢？",
    nutrition_daily_article3_breakdown: "拆解法：把这道菜拆分成基本成分(例如：面条+鸡胸肉+一勺油+酱料)。",
    nutrition_daily_article3_estimate: "估算法：不确定？在食物数据库中搜索一道相似的菜，获得一个不错的平均估算值。",
    nutrition_daily_article3_control: "完全掌控：想要最高精度？在家用您准确的食材制作这道餐，并把它保存为应用中的预设餐！🎯",
    meal_photo_scan_title: "扫描食物照片（高级版）", meal_photo_scan_btn: "扫描食物照片（高级版）", meal_photo_loading_text: "正在分析您的食物...",
