    faq_q_daily_focus_prompt: "那个问我今天最重要要做什么的小提醒是什么？", faq_a_daily_focus_prompt: "这是Premium每日提醒：每天一次，AI助手图标上会出现一个小小的「1」徽章。点击徽章会打开一个气泡，询问今天对您来说最重要的事是什么，里面直接显示5条现成建议(每天更换，在一整年的不同主题中轮换，保持新鲜感)，以及可自行填写的「其他」 - 可以选择多项。点击添加后，您选择的内容会以小提醒标签的形式显示在「我的一天」顶部(它们不是需要勾选的任务)。如果用✕关闭或点击外部，徽章不会消失，而只是在当天剩余时间里变淡。它默认开启，您可以在设置 > 个性化与日历中关闭。今天不合适？点「🌙 今天先不」，徽章会消失到明天，然后问题照常回来。其中一条建议来自你自己的生活——本月目标的下一步或今天的阅读。每天都是全新的开始。",
